        focus = child;
        state.anchor = null;
        state.query = "";
        updateFocus = null;
        break;
      }
      case "GO_BACK": {
        const parent = node.origin?.anchor.thread;
        if (parent === undefined) state.split = false;
        else focus = parent;
        state.anchor = null;
        state.query = "";
        updateFocus = null;
        break;
      }
      case "TOGGLE_EXPANDED": {
        const set = expandedFor(focus);
        if (!set.delete(msg.index)) set.add(msg.index);
        break;
      }
      case "SELECTION_CHANGED":
        state.anchor = msg.anchor;
        node.activeChild = null;
        updateFocus = null;
        break;
      case "MARK_CLICKED":
        state.anchor = null;
        node.activeChild = msg.thread;
        updateFocus = null;
        break;
      case "SHOW_UPDATE":
        showUpdate(focus, msg.index);
        break;
      case "UPDATE_MSG":
        switch (msg.msg.type) {
          case "CLOSE":
            updateFocus = null;
            break;
          case "TOGGLE_EXPANDED": {
            if (updateFocus === null) break;
            const set = updateExpandedFor(updateFocus);
            if (!set.delete(msg.msg.index)) set.add(msg.msg.index);
            break;
          }
        }
        break;
      case "LEARNING_MSG":
        switch (msg.msg.type) {
          case "ACTION": {
            const anchor = state.anchor;
            if (!anchor || overlaps(state.marks, anchor)) break;
            const id = tree.open(anchor, msg.msg.action, {
              tools: readTools(graph),
              graph: graph.render(),
            });
            state.anchor = null;
            state.query = "";
            void queueGraphUpdate(id, 0 as MessageIdx);
            tree
              .get(id)
              .thread.start()
              .then(undefined, (e: unknown) => {
                console.error(e);
              });
            break;
          }
          case "QUERY_CHANGED":
            state.query = msg.msg.query;
            break;
        }
        break;
      case "CHILD_MSG": {
        const activeChild = node.activeChild;
        if (!activeChild) break;
        switch (msg.msg.type) {
          case "DRAFT_CHANGED":
            tree.get(activeChild).draft = msg.msg.draft;
            break;
          case "SUBMIT":
            send(activeChild);
            break;
          case "TOGGLE_EXPANDED": {
            const set = expandedFor(activeChild);
            if (!set.delete(msg.msg.index)) set.add(msg.msg.index);
            break;
          }
          case "CHANGE_CLICKED":
            update(state, msg.msg);
            break;
          case "SHOW_UPDATE":
            showUpdate(activeChild, msg.msg.index);
            break;
        }
        break;
      }
    }
    refresh();
  }

  // Scroll and flash are the one thing that cannot live in a reducer or a
  // binding: they need the DOM to already reflect the new focus.
  const bus = new PostRenderEventBus<AppEvent>();

  let dispatching = false;
  function dispatch(msg: Msg): void {
    if (dispatching) throw new Error("dispatch-in-dispatch");
    dispatching = true;
    update(state, msg);
    view.sync(state);
    save();
    bus.flush();
    dispatching = false;
  }

  // e2e specs seed a known graph through this handle rather than driving the
  // extraction thread first, so the sidebar cases stay deterministic.
  (window as unknown as { __graph?: KnowledgeGraph }).__graph = graph;

  refresh();
  const view = new AppView(container, dispatch, state, { bus });

  // An interaction with no `done` update in the snapshot is one whose update
  // never landed - the page went away while it was running - so it is replayed
  // in the order it was first asked in.
  if (snapshot) {
    const pending = interactionAddresses(
      snapshot.threads,
      snapshot.root,
      snapshot.build.type !== "idle",
      sampleTurnCount,
    ).filter(({ thread, index }) => !graphUpdates.has(address(thread, index)));
    if (state.build.type === "running") {
      state.build = {
        type: "running",
        done: sampleInteractions.filter((index) =>
          graphUpdates.has(address(tree.root, index)),
        ).length,
        total: sampleInteractions.length,
        failures: [],
      };
    }
    if (pending.length > 0) void drain(pending);
    else {
      finishBuild();
      sync();
    }
  }
}

import type { ThreadId } from "./selection.ts";
import { type Message, type MessageIdx, messageText } from "./thread.ts";
import type { ThreadTree } from "./threads.ts";

/** One user interaction, captured as it happens. The unit of evidence about
 * what this user understands. */
export type Interaction = {
  thread: ThreadId;
  /** Index into that thread's `messages`. With `thread`, this is the citable
   * address. A learning thread's ask is its own message 0, so there is no
   * special case. */
  index: MessageIdx;
  /** The thread's seed, then its blocks before the turn - which are messages
   * 0 to index-1, so their addresses are their positions. Identical across
   * interactions in the same thread up to their split point; the prompt cache
   * depends on that. */
  prefix: {
    seed: string | undefined;
    messages: ReadonlyArray<Message>;
  };
  /** The user's turn. */
  text: string;
};

/** The interaction the user just made: the turn at `index` in `thread`. */
export function interactionAt(
  tree: ThreadTree,
  thread: ThreadId,
  index: MessageIdx,
): Interaction {
  const node = tree.get(thread);
  const messages = node.thread.messages;
  const message = messages[index];
  if (!message) {
    throw new Error(`no message ${index} in thread ${thread}`);
  }
  if (message.role !== "user") {
    throw new Error(`message ${index} in thread ${thread} is not a user turn`);
  }
  return {
    thread,
    index,
    prefix: {
      // Only a learning thread's seed is prose; a graph update's seed is
      // content blocks, and those threads have no interactions in them.
      seed: typeof node.thread.seed === "string" ? node.thread.seed : undefined,
      messages: messages.slice(0, index),
    },
    text: messageText(message),
  };
}

